class MyPromise {
  #state = 'pending';
  #value = undefined;
  #handlers = [];

  constructor(executor) {
    const resolve = (value) => {
      if (this.#state !== 'pending') return;
      this.#state = 'fulfilled';
      this.#value = value;
      this.#handlers.forEach(h => this.#run(h));
    };
    const reject = (reason) => {
      if (this.#state !== 'pending') return;
      this.#state = 'rejected';
      this.#value = reason;
      this.#handlers.forEach(h => this.#run(h));
    };
    try { executor(resolve, reject); } catch (e) { reject(e); }
  }

  #run({ onFulfilled, onRejected, childResolve, childReject }) {
    queueMicrotask(() => {
      try {
        const fn = this.#state === 'fulfilled' ? onFulfilled : onRejected;
        const result = fn ? fn(this.#value) : this.#value;
        if (this.#state === 'rejected' && !onRejected) { childReject(this.#value); return; }
        childResolve(result);
      } catch (err) { childReject(err); }
    });
  }

  then(onFulfilled, onRejected) {
    return new MyPromise((childResolve, childReject) => {
      const handler = { onFulfilled, onRejected, childResolve, childReject };
      if (this.#state === 'pending') this.#handlers.push(handler);
      else this.#run(handler);
    });
  }
}

new MyPromise((resolve) => resolve(1))
  .then((x) => x + 1)
  .then((x) => { throw new Error(`fail at ${x}`); })
  .catch((err) => err.message)
  .then((msg) => console.log(msg));
